import * as FileSystem from "expo-file-system/legacy";
import * as Print from "expo-print";
import * as Sharing from "expo-sharing";

/**
 * Fetch a print HTML endpoint from the API server, render it to PDF on device
 * using expo-print (WKWebView on iOS / Chromium on Android), then open the
 * native share sheet so the user can save / AirDrop / mail it.
 *
 * The HTML is generated by `@workspace/print-html` so the output is identical
 * to the web 版.
 */
export async function printApiDoc(opts: {
  path: string; // "/api/print/invoice/:id"
  fileName: string; // "請求書-INV001.pdf"
  getToken: () => Promise<string | null>;
}): Promise<void> {
  const domain = process.env.EXPO_PUBLIC_DOMAIN;
  if (!domain) throw new Error("EXPO_PUBLIC_DOMAIN が未設定です");
  const token = await opts.getToken();
  const url = `https://${domain}${opts.path}`;
  const res = await fetch(url, {
    headers: token ? { Authorization: `Bearer ${token}` } : {},
  });
  if (!res.ok) {
    throw new Error(`PDF 取得失敗 (HTTP ${res.status})`);
  }
  const html = await res.text();

  // Render PDF
  const { uri } = await Print.printToFileAsync({ html, base64: false });

  // Move to a stable filename for the share sheet
  let shareUri = uri;
  try {
    const dir = FileSystem.cacheDirectory ?? "";
    const target = `${dir}${opts.fileName}`;
    await FileSystem.copyAsync({ from: uri, to: target });
    shareUri = target;
  } catch {
    // fall back to original URI on copy failure
  }

  if (await Sharing.isAvailableAsync()) {
    await Sharing.shareAsync(shareUri, {
      mimeType: "application/pdf",
      dialogTitle: opts.fileName,
      UTI: "com.adobe.pdf",
    });
  }
}
